import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test("A file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const name = uniqueName("DOC-05 Vendor");
  const created = await member.post("/api/vendors", {
    data: {
      name,
      category: "services",
      contact_email: `doc05.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };
  const content = Buffer.alloc(TEN_MIB, "a");

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "contract",
      file: {
        name: "contract-10mib.txt",
        mimeType: "text/plain",
        buffer: content,
      },
    },
  });

  // Assert
  expect(response.status(), await response.text()).toBe(201);
});
